CREATE TABLE IF NOT EXISTS shift_today_checkins (user_id INTEGER NOT NULL,local_date TEXT NOT NULL,mood TEXT NOT NULL,guts TEXT NOT NULL,energy TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,local_date));
CREATE TABLE IF NOT EXISTS shift_today_choices (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,local_date TEXT NOT NULL,domain TEXT NOT NULL,choice_key TEXT NOT NULL,choice_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,local_date,domain));
CREATE TABLE IF NOT EXISTS shift_treatment_context (user_id INTEGER PRIMARY KEY,medicine TEXT NOT NULL,route TEXT NOT NULL,dose TEXT NOT NULL,week_number INTEGER,next_dose_on TEXT,next_delivery_on TEXT,status TEXT NOT NULL DEFAULT 'active',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_shift_today_choices_user_date ON shift_today_choices(user_id,local_date);
